window.NPC_CHUNK_192 = [{"name":"Varlaikal","cr":12,"xp":19200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"alchemist","level":13}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":31,"ac_touch":16,"ac_flat_footed":25,"ac_mods":"+8 armor, +1 deflection, +4 Dex, +1 dodge, +7 natural","hp":101,"hd":"13d8+39","hd_value":13,"fort":10,"ref":13,"will":7,"immunities":["poison"],"speed":[{"type":"land","speed":30}],"melee":"mwk sickle +14 (1d6-1 plus poison)","ranged":"+1 blowgun +15 (1d2+1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"18/day, 7d6+5 fire, DC 21"}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":13,"extractsprepared":[{"spell_level":5,"spells":[{"spell":"dust form"},{"spell":"languid bomb admixture"}]},{"spell_level":4,"spells":[{"spell":"cure critical wounds"},{"spell":"detonate"},{"spell":"stoneskin"},{"spell":"viper bomb admixture"}]},{"spell_level":3,"spells":[{"spell":"absorb toxicity"},{"spell":"cure serious wounds"},{"spell":"fly"},{"spell":"haste"},{"spell":"protection from energy"}]},{"spell_level":2,"spells":[{"spell":"barkskin"},{"spell":"cat's grace"},{"spell":"defensive shock"},{"spell":"invisibility"},{"spell":"touch injection"},{"spell":"transmute potion to poison"}]},{"spell_level":1,"spells":[{"spell":"cure light wounds","count":2},{"spell":"enlarge person"},{"spell":"expeditious retreat"},{"spell":"reduce person"},{"spell":"shield"},{"spell":"true strike"}]}],"strength":8,"dexterity":18,"constitution":13,"intelligence":20,"wisdom":10,"charisma":10,"baseatk":9,"cmb":8,"cmd":24,"feats":[{"feat":"Brew Potion"},{"feat":"Dodge"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Throw Anything"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (blowgun)"}],"skills":[{"skill":"Craft (alchemy)","value":21},{"skill":"Disable Device","value":19},{"skill":"Fly","value":19},{"skill":"Heal","value":16},{"skill":"Knowledge (arcana)","value":21},{"skill":"Knowledge (nature)","value":21},{"skill":"Perception","value":16},{"skill":"Sleight of Hand","value":19},{"skill":"Spellcraft","value":21},{"skill":"Survival","value":16}],"languages":["Common","Celestial","Draconic","Giant","Infernal","Kelish"],"sq":["alchemy (alchemy crafting +13, identify potions)","discoveries (concentrate poison, poison bomb [13 rounds/level], poison conversion, preserve organs, smoke bomb, sticky poison [5 strikes])","mutagen (+4/-2, +2 natural, 130 minutes)","poison use","swift alchemy","swift poisoning"],"gear":"+4 chain shirt, +1 blowgun with 40 blowgun darts, mwk sickle, cloak of resistance +1, ring of protection +1, alchemist's lab, keys to areas F6 and F12, diamond dust (worth 250 gp), deathblade poison (2 doses), giant wasp poison (2 doses), purple worm poison (4 doses), wyvern poison (1 dose)","before_combat":"Varlaikal keeps his sickle coated with a concentrated dose of purple worm poison, which lasts for five attacks. If he hears combat, he drinks his barkskin extract and his mutagen to augment his Dexterity.","during_combat":"Varlaikal begins by consuming his dust form extract, then throwing poison bombs to blanket the room in toxic gas. He then consumes his viper bomb admixture extract and reverts to standard bombs.","morale":"If reduced below 20 hit points, Varlaikal attempts to flee.","base_statistics":"Without his barkskin extract and his mutagen, Varlaikal has the following statistics: AC 22, touch 14, flat-footed 18; Ref +11, Will +8; Ranged +1 blowgun +12/+7; Dex 14, Wis 12; CMD 22; Skills Disable Device +17, Fly +17, Heal +17, Perception +17, Sleight of Hand +17, Survival +17.","source":"Feast Of Dust, Pathfinder RPG Advanced Player's Guide 26"},{"name":"Jackal Prince","cr":16,"xp":76800,"race":"meladaemon","gender":"Male","age_category":"Adult","alignment":"NE","size":"Medium","type":"outsider","sub_types":["daemon","evil","extraplanar"],"init":10,"senses":["darkvision 60 ft."],"auras":["consumptive aura (20 ft., DC 26)"],"ac":32,"ac_touch":16,"ac_flat_footed":26,"ac_mods":"+4 armor, +6 Dex, +12 natural","hp":243,"hd":"18d10+144","hd_value":18,"hp_mods":"fast healing 5","fort":18,"ref":14,"will":15,"dr":"10/good","immunities":["acid","death effects","disease","poison"],"resists":["acid 10","cold 10","electricity 10","fire 10"],"sr":27,"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"Ravenous Blade +27 (2d4+12/18-20 plus 1d6 nonlethal and 1 nonlethal bleed), bite +21 (2d6+3 plus disease) or 2 claws +26 (1d10+7/19-20 plus hunger), bite +26 (2d6+7 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"corrupted weapons"},{"type":"disease"},{"type":"hunger"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"feast of ashes"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"horrid wilting"},{"spell":"summon","details":"meladaemonB2 45%, level 8"},{"spell":"unholy aura"},{"spell":"waves of exhaustion"}]},{"frequency":"3/day","spells":[{"spell":"bestow curse"},{"spell":"contagion"},{"spell":"dispel good"},{"spell":"displacement"}]}],"strength":25,"dexterity":22,"constitution":24,"intelligence":16,"wisdom":18,"charisma":25,"baseatk":18,"cmb":25,"cmd":41,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Bluff","value":28},{"skill":"Diplomacy","value":16},{"skill":"Fly","value":10},{"skill":"Knowledge (arcana, history)","value":15},{"skill":"Knowledge (planes)","value":24},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":24},{"skill":"Stealth","value":27},{"skill":"Survival","value":15},{"skill":"Use Magic Device","value":24}],"languages":["Common","Abyssal","Draconic","Infernal","telepathy 100 ft."],"special_abilities":[{"type":"Consumptive Aura","kind":"Su","details":"Like a normal meladaemon, the Jackal Prince radiates an aura of hunger to a radius of 20 feet. Every round a creature begins its turn within this aura, it must succeed at a DC 26 Fortitude save or take 1d6 points of nonlethal damage and become fatigued from extreme hunger. Creatures that don't need to eat are immune to this effect. The save DC is Constitution-based."},{"type":"Corrupted Weapons","kind":"Su","details":"The Jackal Prince's natural weapons-as well as any weapons he wields-are treated as evil for the purpose of overcoming damage reduction."},{"type":"Disease","kind":"Su","details":"Daemonic Wasting: bite-injury; save Fort DC 26; onset 1 day; frequency 1 day; effect 1d4 Con and 1d4 Cha damage; cure 2 consecutive saves."},{"type":"Hunger","kind":"Su","details":"The Jackal Prince's claw attacks and attacks with the Ravenous Blade deal an extra 2d6 points of nonlethal damage as it causes terrible pangs of hunger. Creatures that don't need to eat are immune to this additional damage."}],"gear":"+2 leather, Ravenous Blade (+2 wounding falchion), minor ring of energy resistance (acid), ring of evasion","before_combat":"If aware of an imminent attack, the Jackal Prince casts displacement and devours a fruit from the Tree of Desolation, gaining fast healing 2.","during_combat":"The Jackal Prince begins combat with waves of exhaustion to weaken his foes. He then uses another of his powerful spell-like abilities before closing to melee range and allowing his aura to further weaken anyone not affected by his previous effects. The Jackal Prince tries to grapple weak characters and impale them on the Tree of Desolation.","morale":"Unwilling to give up now, the Jackal Prince fights to the death.","source":"Feast Of Dust, Pathfinder RPG Bestiary 2 69","unique_monster":1},{"name":"Kasa-Obake","cr":4,"xp":1200,"race":"Kasa-Obake","age_category":"Adult","alignment":"N","size":"Small","type":"outsider","sub_types":["kami","native"],"init":3,"senses":["darkvision 60 ft.","low-light vision"],"ac":20,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+3 Dex, +6 natural, +1 size","hp":27,"hd":"2d10+16","hd_value":2,"hp_mods":"fast healing 5","fort":3,"ref":6,"will":6,"defensive_abilities":["hardness 5"],"immunities":["construct traits","petrification","polymorph"],"resists":["acid 10","electricity 10","fire 10"],"speed":[{"type":"land","speed":30}],"melee":"3 slams +6 (1d6+2) Spell-like Abilities (CL 2nd; concentration +4) At-will-decrepit disguise (self only), ghost sound, invisibility (self only), mending, quintessence (self only), ventriloquism","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":16,"constitution":17,"intelligence":15,"wisdom":17,"charisma":14,"baseatk":2,"cmb":3,"cmd":16,"feats":[{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Bluff","value":7},{"skill":"Craft (cloth)","value":7},{"skill":"Disguise","value":7},{"skill":"Knowledge (history)","value":7},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":12}],"languages":["Common","telepathy 100 ft."],"sq":["construction points (additional attack)","freeze","merge with ward","ward (100-year-old umbrella)"],"source":"PFRPG Bestiary 5"},{"name":"Boroboroton","cr":5,"xp":1600,"race":"Boroboroton","age_category":"Adult","alignment":"NE","size":"Medium","type":"outsider","sub_types":["kami","native"],"init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+2 Dex, +1 dodge, +6 natural","hp":48,"hd":"3d10+32","hd_value":3,"hp_mods":"fast healing 5","fort":5,"ref":5,"will":6,"defensive_abilities":["hardness 5"],"immunities":["construct traits","petrification","polymorph"],"resists":["acid 10","electricity 10","fire 10"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +8 (1d8+4 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d8+4"}],"strength":18,"dexterity":14,"constitution":19,"intelligence":15,"wisdom":17,"charisma":14,"baseatk":3,"cmb":7,"cmb_special":"+11 grapple","cmd":20,"feats":[{"feat":"Dodge"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Craft (cloth)","value":8},{"skill":"Disguise","value":8},{"skill":"Knowledge (history)","value":8},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":9},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":8}],"languages":["Common","telepathy 100 ft."],"sq":["construction points (grab, constrict)","freeze","merge with ward","ward (100-year-old sleeping mat)"],"source":"PFRPG Bestiary 5"},{"name":"Tombus Regegious","cr":12,"xp":19200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":4},{"class":"rogue","level":9}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":9,"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+4 armor, +4 Dex, +1 dodge, +1 shield","hp":88,"hd":"13d8+26","hd_value":13,"fort":8,"ref":12,"will":9,"defensive_abilities":["evasion","improved uncanny dodge","trap sense +3"],"speed":[{"type":"land","speed":35}],"melee":"+1 flaming short sword +14 (1d6+2/17-20 plus 1d6 fire), +1 flaming short sword +14 (1d6+1/17-20 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+5d6"}],"strength":13,"dexterity":20,"constitution":14,"intelligence":8,"wisdom":10,"charisma":14,"baseatk":9,"cmb":10,"cmd":26,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Fleet"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (short sword)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Two-Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Bluff","value":18},{"skill":"Diplomacy","value":18},{"skill":"Intimidate","value":18},{"skill":"Knowledge (local)","value":15},{"skill":"Linguistics","value":3},{"skill":"Perception","value":16},{"skill":"Sleight of Hand","value":19},{"skill":"Stealth","value":11}],"languages":["Common","Infernal"],"sq":["rogue talents (combat trick, finesse rogue, offensive defense, weapon training)","trapfinding +4"],"gear":"chain shirt, +1 flaming short swords (2), belt of incredible dexterity +2, 280 gp","during_combat":"Tombus seeks to flank PCs at the edges of his troop, commanding the soldiers to shift and reconfigure in whatever shape is necessary so that he can make full attacks and take full advantage of his sneak attacks.","morale":"Tombus attempts to flee if reduced to 20 or fewer hit points-if he does so, he goes into hiding. He may show up later alongside another Thrune ally, but it's more likely that the next time the PCs encounter him, he'll be in a semi-conscious state near death in the inquisitors' workshop (area E15) of the Temple of Asmodeus, being punished for his failure.","source":"AP 100"},{"name":"Strea Vestori","cr":9,"xp":6400,"race":"Tiefling","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":10}],"alignment":"CN","size":"Medium","type":"outsider","sub_types":["native"],"init":3,"senses":["darkvision 60 ft."],"ac":14,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 shield","hp":78,"hd":"10d8+30","hd_value":10,"fort":5,"ref":10,"will":2,"defensive_abilities":["evasion","improved uncanny dodge","trap sense +3"],"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":30}],"melee":"+1 dagger +10 (1d4+1/19-20), +1 dagger +10 (1d4+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+5d6"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"2/day","spells":[{"spell":"vanish"}]},{"frequency":"3/day","spells":[{"spell":"message"}]}],"strength":10,"dexterity":16,"constitution":14,"intelligence":14,"wisdom":8,"charisma":14,"baseatk":7,"cmb":7,"cmd":20,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Feint"},{"feat":"Quick Draw"},{"feat":"Two-weapon Defense"},{"feat":"Two-weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (dagger)"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Bluff","value":17},{"skill":"Climb","value":13},{"skill":"Disable Device","value":19},{"skill":"Disguise","value":15},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Sleight of Hand","value":16},{"skill":"Stealth","value":23},{"skill":"Survival","value":9}],"languages":["Common","Abyssal","Halfling","Infernal"],"sq":["rogue talents (combat trick, finesse rogue, major magic, minor magic, weapon training)","trapfinding +5"],"gear":"+2 studded leather, +1 daggers (2), cloak of elvenkind, 21 gp, potion of barkskin (CL 6th), potion of cure light wounds (5)","during_combat":"Strea drinks a potion of barkskin on the first round of combat, then uses Quick Draw to retrieve her second dagger. She uses Improved Feint to maximize her sneak attacks unless she's fighting with allies, in which case she prefers to flank and make full attacks. If reduced to 30 or fewer hit points, she casts vanish and then retreats to Natsiel's side in area A4.","morale":"As long as she remains charmed, Strea fights to the death. If the charm is dispelled, she immediately surrenders-see Development below.","source":"AP 100, Pathfinder RPG Bestiary 264"},{"name":"Natsiel","cr":11,"xp":12800,"race":"human","age_category":"Adult","classes":[{"class":"sorcerer","level":10}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["human","humanoid","native"],"templates_applied":"half-succubus","init":4,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+4 armor, +4 Dex, +1 natural","hp":122,"hd":"10d6+85","hd_value":10,"fort":12,"ref":9,"will":11,"dr":"5/magic","immunities":["poison"],"resists":["acid 10","cold 10","electricity 10","fire 10"],"sr":22,"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 Human-bane rhoka sword +10 (1d8+8/18-20), bite +5 (1d6+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"claws","details":"2, 1d6, treated as magic weapons, 8 rounds/day"},{"type":"passion"},{"type":"smite good"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"detect thoughts"},{"spell":"dominate person"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"darkness"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":10,"spellsknown_concentration":15,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"feeblemind"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"dimension door"},{"spell":"greater invisibility"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"fly"},{"spell":"haste"},{"spell":"hold person"},{"spell":"rage"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bull's strength"},{"spell":"false life"},{"spell":"mirror image"},{"spell":"scorching ray"},{"spell":"touch of idiocy"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cause fear"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"reduce person"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"arcane mark"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"}]}],"bloodline":"Abyssal","strength":18,"dexterity":18,"constitution":20,"intelligence":12,"wisdom":10,"charisma":20,"baseatk":5,"cmb":9,"cmd":23,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Casting"},{"feat":"Craft Wondrous Item"},{"feat":"Eschew Materials"},{"feat":"Exotic Weapon Proficiency (rhoka sword)"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Bluff","value":18},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":10},{"skill":"Spellcraft","value":14}],"languages":["Common","Abyssal"],"sq":["bloodline arcana (summoned creatures gain DR 4/good)","change shape","strength of the Abyss"],"special_abilities":[{"type":"Passion","kind":"Su","details":"Natsiel drains energy from a mortal she lures into an act of passion-unwilling victims must be grappled before she can use this ability. The passion bestows 1 negative level. She can use this ability up to 10 times a day; removing 1 of these negative levels requires a successful DC 20 Fortitude save."}],"gear":"+1 Human-bane rhoka sword, amulet of mighty fists +1, belt of mighty constitution +2, boots of elvenkind, cloak of resistance +2, key (unlocks all doors in the area), 775 gp","before_combat":"Natsiel casts false life at the start of every day, as well as mage armor.","during_combat":"Natsiel casts greater invisibility on the first round of combat, then stoneskin, shield and bull's strength over the next few rounds (or once the alarm is raised, either by Strea in room A3 or by hearing PCs hammering on the doors to the north from area A8). She relies on her green hags to distract foes while casting these spells, then switches over to spells like feeblemind, dominate person, scorching ray, and magic missile. If she enters melee combat, she tries to cast haste first. In any event, she always uses Arcane Strike to bolster her damage (this +3 bonus on damage rolls is calculated into her attacks above). Once her greater invisibility spell is about to expire (or as soon after it's dispelled), she casts mirror image.","morale":"If reduced to 30 or fewer hit points, Natsiel uses dimension door to teleport out of the area to the city above, then flees to the Church of Asmodeus to offer her aid to Barzillai Thrune in destroying the PCs. Barzillai doesn't trust Natsiel that much, but knows that he can use as many allies as he can secure. He agrees to provide healing to the half-succubus and to assign her several erinyes devils as minions. Natsiel can make additional attacks on the PCs for the remainder of the adventure as you see fit, and could even be part of the final retaliatory attack on the PCs during the celebration at the end of the adventure.","source":"AP 100, Pathfinder Campaign Setting: Demons Revisited 54"},{"name":"Guttugger","cr":7,"xp":3200,"race":"deinonychus dinosaur","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"CG","size":"Medium","type":"magical beast","sub_types":["animal"],"templates_applied":"awakened","init":9,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":20,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+1 deflection, +5 Dex, +1 dodge, +3 natural","hp":88,"hd":"8d8+34","hd_value":8,"fort":9,"ref":14,"will":7,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":60}],"melee":"bite +12 (1d6+5), claw +7 (1d4+3), 2 talons +13 (1d8+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"sneak attack","details":"+2d6"}],"strength":19,"dexterity":20,"constitution":17,"intelligence":7,"wisdom":14,"charisma":18,"baseatk":7,"cmb":11,"cmd":28,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Weapon Focus (talon)"}],"skills":[{"skill":"Acrobatics","value":26,"special":"+24 to jump"},{"skill":"Perception","value":23},{"skill":"Stealth","value":26}],"languages":["Elven"],"sq":["rogue talents (bleeding attack +2, weapon training)","trapfinding +2"],"gear":"amulet of mighty fists +1, ring of protection +1","during_combat":"Guttugger attempts to charge a flat-footed foe on the first round of combat to maximize his sneak attacks with a pounce. If reduced to 40 or fewer hit points, he flees, hides, and awaits a chance to make another pouncing sneak attack.","morale":"Guttugger flees combat if reduced to 20 or fewer hit points unless he's fighting at Shensen's side, in which case he fights to the death.","source":"AP 100, Pathfinder RPG Bestiary 84"},{"name":"Tiarise Izoni","cr":10,"xp":9600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"witch","level":11,"archetype":"dimensional occultist"}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":19,"ac_touch":16,"ac_flat_footed":19,"ac_mods":"+4 armor, +2 Dex, +1 dodge, +2 natural","hp":78,"hd":"11d6+37","hd_value":11,"fort":8,"ref":7,"will":9,"speed":[{"type":"land","speed":30}],"melee":"+1 dagger +5 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"disguise, flight, retribution, slumber"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"feather fall","details":"self only"},{"spell":"fly","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"levitate","details":"self only"}]},{"frequency":"1/week","spells":[{"spell":"commune with familiar"}]}],"spellsprepared_caster":"witch","spellsprepared_caster_level":11,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":6,"spell_slots":1,"spells":[{"spell":"flesh to stone"}]},{"spell_level":5,"spell_slots":2,"spells":[{"spell":"feeblemind"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"charm monster"},{"spell":"cure serious wounds"},{"spell":"dimension door"},{"spell":"phantasmal killer"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"bestow curse"},{"spell":"dispel magic"},{"spell":"lightning bolt"},{"spell":"speak with dead"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds"},{"spell":"false life"},{"spell":"hold person"},{"spell":"rope trick"},{"spell":"status"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"cure light wounds","count":2},{"spell":"mage armor"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"light"},{"spell":"touch of fatigue"}]}],"patron":"Dimensions","strength":8,"dexterity":14,"constitution":12,"intelligence":18,"wisdom":10,"charisma":14,"baseatk":5,"cmb":4,"cmd":17,"feats":[{"feat":"Combat Casting"},{"feat":"Craft Wand"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Familiar"},{"feat":"Scribe Scroll"}],"skills":[{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (history)","value":18},{"skill":"Knowledge (religion)","value":15},{"skill":"Linguistics","value":15},{"skill":"Perception","value":11},{"skill":"Spellcraft","value":18},{"skill":"Swim","value":3},{"skill":"Use Magic Device","value":16}],"languages":["Common","Abyssal","Aklo","Azlanti","Celestial","Dwarven","Elven","Gnome","Halfling","Infernal","Necril","Shadowtongue","Strix","Tengu","Undercommon","Varisian"],"sq":["dimensional augmentation","witch's familiar (devil, imp named Kelaxiax)"],"special_abilities":[{"type":"Commune with Familiar","kind":"Sp","details":"Once per week, Tiarise can use her link with her familiar Kelaxiax to cast contact other plane as a spell-like ability. The entity contacted replies via Kelaxiax, speaking through the familiar in a disconcertingly deep voice. Tiarise gains a +4 bonus on the Intelligence check to avoid ability score decreases when using the spell in this way, and such decreases last only 24 hours rather than a number of weeks."},{"type":"Dimensional Augmentation","kind":"Su","details":"Up to five times per day, Tiarise can augment her spells by incorporating complex mathematical equations in a ritualized manner while casting, inscribing the equations on a nearby surface with chalk or ink. Doing so adds a somatic component and a material component (the chalk equations), and increases the spell's casting time to a number of rounds equal to the spell's level (if the spell's casting time is 1 minute or longer, it isn't altered). Augmenting a spell in this way increases its effective caster level by 1. Dimensions Patron Tiarise gains the following bonus spells from this patron (although she normally doesn't prepare all of them): blink, dimensional anchor, hold portal, lesser planar binding, and rope trick."}],"gear":"+1 dagger, amulet of natural armor +2, cloak of resistance +2, handy haversack, platinum unholy symbol of Mephistopheles, Records Hall key, rope (10 feet), spell component pouch, adamantine key worth 300 gp (for the matching box in the vault), 5 pp, 5 gp, potion of shield of faith +3 (3), scroll of charm monster, scroll of cure serious wounds, scroll of death ward, scroll of dispel magic, scroll of raise dead,  scroll of speak with dead, scroll of planar binding, scroll of true seeing, scroll of zone of truth, wand of alter self (16 charges), wand of cure moderate wounds (19 charges), wand of detect secret doors (14 charges)","before_combat":"Every day, Tiarise casts false life, mage armor, and unseen servant, all at caster level 12th via dimensional augmentation. She casts status in this manner as well, targeting her imp Kelaxiax, both of her invisible stalkers, and her hellcat Megonya. Tiarise drinks a potion of shield of faith just before combat.","during_combat":"Tiarise begins combat with her most dangerous spells-flesh to stone, feeblemind, and phantasmal killer, avoiding melee combat if possible. She retreats to take cover in the inquisitor troop if no other option is available, although doing so forces her to attempt concentration checks to cast spells. If reduced to 50 or fewer hit points, she uses vampiric touch, delivered by her imp familiar, on the most heavily wounded PC. She commands her unseen servant to pick up any items the PCs drop in combat, to open and close doors to break line of sight, or otherwise force the PCs to waste valuable time.","morale":"If reduced to fewer than 20 hp, Tiarise casts dimension door to teleport to area B3, where she casts rope trick on the bell cord to go into hiding. Therein, she casts her healing spells before emerging to take up the battle again. If reduced to 20 hp or less a second time, she casts teleport to flee to the Temple of Asmodeus-the PCs can confront her again at Barzillai's side, and this time, she doesn't flee. If Tiarise is slain, her body swiftly fades away into a coil of shrieking mist that then dissipates, leaving her gear behind but no body. This begins her transformation into an undead guardian, which won't reach its conclusion until the final adventure, \"Breaking the Bones of Hell.\" Methods exist to prevent this transformation from occurring, such as taking care to kill Tiarise while she is in the area of effect of a hallow spell, but once she's slain and the transformation begins, the PCs are destined to face her again in the final adventure.","source":"AP 100, Pathfinder RPG Advanced Player's Guide 65, Pathfinder Campaign Setting: Pathfinder Society Field Guide 28"},{"name":"Kelaxiax","xp":0,"race":"imp","gender":"Male","age_category":"Adult","alignment":"LE","size":"Tiny","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":3,"senses":["darkvision 60 ft."],"ac":23,"ac_touch":16,"ac_flat_footed":19,"ac_mods":"+3 Dex, +1 dodge, +7 natural, +2 size","hp":39,"hd":"3d10","hd_value":3,"hp_mods":"fast healing 2","fort":3,"ref":6,"will":8,"dr":"5/good or silver","immunities":["fire","poison"],"resists":["acid 10","cold 10"],"sr":16,"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"},{"type":"land","speed":20}],"melee":"sting +10 (1d4 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"poison"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"augury"},{"spell":"suggestion"}]},{"frequency":"1/week","spells":[{"spell":"commune","details":"CL 12th, 6 questions"}]}],"strength":10,"dexterity":17,"constitution":10,"intelligence":14,"wisdom":12,"charisma":14,"baseatk":5,"cmb":6,"cmd":17,"feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":8},{"skill":"Fly","value":21},{"skill":"Knowledge (arcana)","value":16},{"skill":"Knowledge (planes)","value":8},{"skill":"Linguistics","value":13},{"skill":"Perception","value":15},{"skill":"Spellcraft","value":16},{"skill":"Stealth","value":17},{"skill":"Use Magic Device","value":13}],"languages":["Common","Infernal"],"sq":["change shape (boar, giant spider, rat, or raven; beast shape I)","improved evasion"],"during_combat":"Kelaxiax remains invisible and perched atop Tiarise's shoulder. He casts suggestion on the first PC to deal damage to Tiarise, suggesting that PC drop to his knees to beg forgiveness for the assault. He attempts to sting any foe that grapples Tiarise, but otherwise avoids combat for the most part, save for when he's ordered to deliver touch spells-something he prefers to do while invisible.","morale":"If Tiarise is slain, Kelaxiax flees and hides, hoping to avoid the PCs for the rest of his life.","source":"AP 100, Pathfinder RPG Bestiary 78"},{"name":"Skinsaw Cultists","cr":5,"xp":1600,"race":"human","age_category":"Adult","classes":[{"class":"cleric of Norgorber","level":3},{"class":"rogue","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+3 armor, +3 Dex, +1 shield","hp":51,"hd":"6d8+21","hd_value":6,"fort":6,"ref":7,"will":6,"defensive_abilities":["evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"+1 war razor +8 (1d4+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"3/day, DC 11, 2d6"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"5/day","spells":[{"spell":"bleeding touch","details":"1 round"},{"spell":"copycat","details":"3 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":3,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"cure moderate wounds"},{"spell":"hold person"},{"spell":"invisibility","type":"domain"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds","count":2},{"spell":"disguise self","type":"domain"},{"spell":"divine favor"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"}]}],"spelldomains":"Death, Trickery","strength":12,"dexterity":16,"constitution":14,"intelligence":8,"wisdom":15,"charisma":10,"baseatk":4,"cmb":5,"cmd":18,"feats":[{"feat":"Craft Wondrous Item"},{"feat":"Improved Initiative"},{"feat":"Martial Weapon Proficiency (war razor)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Disguise","value":9},{"skill":"Knowledge (local)","value":4},{"skill":"Knowledge (religion)","value":4},{"skill":"Perception","value":11},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":12}],"languages":["Common"],"sq":["rogue talent (finesse rogue)","trapfinding +1"],"gear":"mwk studded leather, mwk buckler, +1 war razor, skinsaw mask, 60 gp","during_combat":"The cultists organize into pairs, with each focusing on a specific PC in order to maximize sneak attack opportunities. If a cultist gets to act in a surprise round, he casts hold person to try to end the fight before it begins. The cultists cast divine favor on the first round of combat, then move to flank foes. A cultist reduced to 20 or fewer hit points casts invisibility, then flees to heal as best he can with his spells before returning to combat to finish the fight.","morale":"A Skinsaw cultist fights to the death.","source":"AP 100"},{"name":"Hei-Fen","cr":12,"xp":19200,"race":"human","age_category":"Old","classes":[{"class":"cleric of norgorber","level":12}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human","shapechanger"],"templates_applied":"natural wererat","init":8,"senses":["low-light vision","scent"],"ac":29,"ac_touch":19,"ac_flat_footed":24,"ac_mods":"+7 armor, +4 deflection, +4 Dex, +1 dodge, +3 natural","hp":117,"hd":"12d8+60","hd_value":12,"fort":11,"ref":8,"will":12,"dr":"10/silver","speed":[{"type":"land","speed":40}],"melee":"+3 agile short sword +16 (1d6+7/19-20) or bite +8 (1d4 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"4/day, DC 17, 6d6"},{"type":"curse of lycanthropy"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charming smile","details":"12 rounds/day"},{"spell":"master's illusion","details":"12 rounds/day"}]},{"frequency":"7/day","spells":[{"spell":"copycat","details":"12 rounds"},{"spell":"dazing touch"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":12,"spellsprepared_concentration":16,"spellsprepared":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"harm"},{"spell":"mislead","type":"domain"},{"spell":"word of recall"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"charm monster","type":"domain"},{"spell":"flame strike"},{"spell":"plane shift"},{"spell":"scrying"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"air walk"},{"spell":"confusion","type":"domain"},{"spell":"cure critical wounds"},{"spell":"greater magic weapon"},{"spell":"poison"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"blindness/deafness"},{"spell":"cure serious wounds","count":2},{"spell":"dispel magic"},{"spell":"magic vestment"},{"spell":"suggestion","type":"domain"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"cure moderate wounds","count":2},{"spell":"enthrall"},{"spell":"invisibility","type":"domain"},{"spell":"spiritual weapon"},{"spell":"status"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"cure light wounds","count":2},{"spell":"disguise self","type":"domain"},{"spell":"divine favor"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"read magic"}]}],"spelldomains":"Charm, Trickery","strength":12,"dexterity":19,"constitution":17,"intelligence":10,"wisdom":18,"charisma":13,"baseatk":9,"cmb":10,"cmd":29,"feats":[{"feat":"Combat Casting"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Selective Channeling"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Knowledge (local)","value":6},{"skill":"Knowledge (religion)","value":12},{"skill":"Perception","value":10},{"skill":"Stealth","value":17}],"languages":["Common","Tien"],"sq":["change forms","lycanthropic empathy"],"gear":"+1 chain shirt, +1 agile short sword, amulet of natural armor +1, belt of physical might +2 (Dex, Con), boots of striding and springing, cloak of elvenkind, contract with Barzillai Thrune to perform murders to help destabilize Kintargans' morale and to supply him with cultists and a jorogumo to aid in defending the temple of Asmodeus in return for the dottari and inquisitors of the church turning a blind eye to her actions in Kintargo, 40 gp, purple worm poison (3)","before_combat":"Hei-Fen casts shield of faith and air walk on herself just before combat, and greater magic weapon on her short sword and magic vestment on her chain shirt before combat. She poisons her sword with a dose of purple worm poison before combat. She always fights in hybrid form to offset her age penalties and to gain a bite attack.","during_combat":"Hei-Fen uses her ranged spells in the first few rounds of combat to soften foes up or to sow discord. When three of her cultists fall, she casts harm, holds the charge, and steps up to deliver the spell to a PC, following up on the next rounds with melee attacks while flanking with surviving cultist allies. She wants to see the PCs die, and resists the urge to use plane shift to send one of them away to Abaddon, but uses this tactic on dangerous conjured foes or non-PC allies. If reduced to 40 or fewer hit points, she casts mislead and then seeks a hiding place to cast healing spells; she then casts poison, holds the charge, and seeks to return to combat with the spell as a touch attack.","morale":"If reduced to 20 hp or fewer, Hei-Fen casts word of recall to flee back to Vyre. She may return to attack the PCs one last time, preferably during the celebrations on the bridge.","source":"AP 100, Pathfinder RPG Bestiary 197"},{"name":"Vannases Trex","cr":9,"xp":6400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"cavalier","level":10}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+7 armor, +2 Dex, +1 dodge, +1 natural","hp":99,"hd":"10d10+40","hd_value":10,"fort":10,"ref":5,"will":4,"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+1 lance +13 (1d8+4/x3)","ranged":"+1 composite longbow +14 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"banner +3"},{"type":"cavalier's charge"},{"type":"challenge","details":"4/day, +10 damage, gain +3 AC"},{"type":"for the king"},{"type":"greater tactician","details":"3/day, Duck and Cover or Shield Wall, swift action, 8 rounds"}],"strength":14,"dexterity":14,"constitution":16,"intelligence":10,"wisdom":8,"charisma":14,"baseatk":10,"cmb":12,"cmd":25,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Duck And Cover"},{"feat":"Iron Will"},{"feat":"Mounted Archery"},{"feat":"Mounted Combat"},{"feat":"Shield Wall"},{"feat":"Toughness"},{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Handle Animal","value":15},{"skill":"Intimidate","value":15},{"skill":"Knowledge (local)","value":13},{"skill":"Knowledge (nobility)","value":13,"special":"+5 on checks involving her sovereign"},{"skill":"Ride","value":11},{"skill":"Sense Motive","value":12}],"languages":["Common"],"sq":["expert trainer +5","lion's call","mount (horse named Thunderscar)","order of the lion"],"gear":"+1 chainmail, +1 composite longbow (+1 Str) with 4 +1 axiomatic arrows and 5 sleep arrows, +1 lance, amulet of natural armor +1, 120 gp","during_combat":"Vannases mounts her horse Thunderscar and emerges from the stables as soon as possible when combat begins (unless delayed, she likely joins the fight at the start of the 4th round-or the 3rd round if the dottari act on the surprise round). She hangs back on the far side of the troops from the PCs and uses her arrows, starting with sleep arrows but then switching to axiomatic arrows against obvious worshipers of chaotic deities. She holds off issuing a challenge until she isolates a particularly dangerous foe among the PCs, at which point she charges that PC with her lance if she can.","morale":"Vannases fights to the death.","source":"AP 100, Pathfinder RPG Advanced Player's Guide 32"},{"name":"Thunderscar","xp":0,"race":"horse","age_category":"Adult","alignment":"N","size":"Large","type":"animal","templates_applied":"advanced","init":3,"senses":["low-light vision","scent"],"ac":23,"ac_touch":13,"ac_flat_footed":19,"ac_mods":"+3 Dex, +1 dodge, +10 natural, -1 size","hp":76,"hd":"9d8+36","hd_value":9,"fort":10,"ref":9,"will":6,"save_mods":"+4 morale bonus vs. enchantment spells and effects","defensive_abilities":["evasion"],"speed":[{"type":"land","speed":50}],"melee":"bite +11 (1d4+6), 2 hooves +11 (1d6+6)","space":"10 ft.","reach":"5 ft.","strength":22,"dexterity":16,"constitution":18,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":6,"cmb":13,"cmd":27,"cmd_special":"31 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":3,"special":"+8 to jump"},{"skill":"Perception","value":16}],"sq":["devotion","tricks (attack, attack any target, combat riding, come, defend, down, fetch, guard, heel, stay, work)"],"source":"AP 100, Pathfinder RPG Bestiary 177"},{"name":"Dottari Captain","cr":5,"xp":1600,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":6}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":18,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+7 armor, +1 Dex","hp":61,"hd":"6d10+24","hd_value":6,"fort":8,"ref":3,"will":3,"save_mods":"Will: +2 vs. fear","speed":[{"type":"land","speed":30}],"melee":"mwk halberd +10 (1d10+4/x3)","ranged":"+1 composite longbow +10 (1d8+7/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"bows +1"}],"strength":16,"dexterity":13,"constitution":16,"intelligence":8,"wisdom":12,"charisma":10,"baseatk":6,"cmb":9,"cmd":20,"feats":[{"feat":"Deadly Aim"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (longbow)"},{"feat":"Weapon Specialization (longbow)"}],"skills":[{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7}],"languages":["Common"],"sq":["armor training 1"],"gear":"+1 breastplate, +1 composite longbow (+3 Str), mwk halberd","during_combat":"The dottari captains prefer to let their troops engage foes while they hang back and use their longbows.","morale":"As long as Vannases lives, her captains fight to the death. If she's defeated, a captain flees combat if reduced to 10 or fewer hit points.","source":"AP 100"},{"name":"Hellknight Phantom Armor","cr":5,"xp":1600,"race":"guardian phantom armor","age_category":"Adult","alignment":"NE","size":"Medium","type":"undead","templates_applied":"advanced","init":7,"senses":["darkvision 60 ft."],"ac":24,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+9 armor, +3 Dex, +2 natural","hp":56,"hd":"3d8+34","hd_value":3,"fort":5,"ref":6,"will":8,"save_mods":"+6 profane bonus vs. channeled positive energy","defensive_abilities":["channel resistance +8"],"immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"+1 longsword +10 (1d8+9/19-20)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":17,"intelligence":11,"wisdom":15,"charisma":14,"baseatk":3,"cmb":7,"cmd":20,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":10},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":11}],"languages":["Common (can't speak)"],"sq":["freeze (suit of armor)"],"gear":"+1 longsword","during_combat":"These undead suits of armor were created in a desecrated area and have additional hit points as a result. In addition, the above statistics assume these creatures are encountered in the area of an active desecrate effect; if encountered outside of such an area, reduce their channel resistance to +2 and reduce all of their saving throws, attack rolls, and damage rolls by 2 as well. These Hellknight phantom armors focus their attacks on obvious worshipers of good deities if possible.","morale":"The phantom armors fight until destroyed.","source":"AP 100, Pathfinder RPG Bestiary 4 288, 213"},{"name":"Kyrre Ekodyre","cr":11,"xp":12800,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":6},{"class":"Hellknight","level":6}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":25,"ac_touch":12,"ac_flat_footed":24,"ac_mods":"+10 armor, +1 deflection, +1 Dex, +3 shield","hp":130,"hd":"12d10+60","hd_value":12,"fort":12,"ref":5,"will":6,"save_mods":"Will: +2 vs. fear","speed":[{"type":"land","speed":30}],"melee":"+1 keen adamantine longsword +19 (1d8+8/17-20)","ranged":"mwk composite longbow +14 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"smite chaos"},{"type":"weapon training","details":"heavy blades +1"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"}]},{"frequency":"4/day","spells":[{"spell":"discern lies"}]}],"strength":18,"dexterity":12,"constitution":18,"intelligence":8,"wisdom":10,"charisma":13,"baseatk":12,"cmb":16,"cmb_special":"+18 sunder","cmd":28,"cmd_special":"30 vs. sunder","feats":[{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Improved Iron Will"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Shield Focus"},{"feat":"Step Up"},{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"},{"feat":"Weapon Specialization (longsword)"}],"skills":[{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":4},{"skill":"Linguistics","value":0},{"skill":"Perception","value":15}],"languages":["Common","Infernal"],"sq":["armor training 1","aura of law","discipline abilities (censor, wrack)","force of will abilities (force of will-compulsion, force of will-fear)","Hellknight armor","Hellknight order (Order of the Rack)"],"gear":"+1 Hellknight plate, heavy steel shield, +1 keen adamantine longsword, mwk composite longbow (+4 Str), belt of mighty constitution +2, ring of protection +1, key ring (opens all cell doors in areas D8 and D9), 165 gp","during_combat":"Kyrre uses her bow at the start of combat if the PCs are hampered by other foes in melee or on the far side of barricades, but is eager to switch to her longsword. In melee, she always uses Power Attack, making a sunder attempt with her first attack and regular attacks thereafter.","morale":"Kyrre fights to the death.","source":"AP 100, Pathfinder Campaign Setting: The Inner Sea World Guide 278"},{"name":"Hellknight Of The Rack","cr":7,"xp":3200,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":5},{"class":"Hellknight","level":3}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"ac":19,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+10 armor, -1 Dex","hp":85,"hd":"8d10+37","hd_value":8,"fort":10,"ref":2,"will":6,"save_mods":"Will: +7 vs. fear","speed":[{"type":"land","speed":30}],"melee":"+1 longsword +14 (1d8+7/19-20)","ranged":"composite longbow +7 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"smite chaos"},{"type":"weapon training","details":"heavy blades +1"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"}]},{"frequency":"4/day","spells":[{"spell":"discern lies"}]}],"strength":17,"dexterity":8,"constitution":16,"intelligence":10,"wisdom":12,"charisma":13,"baseatk":8,"cmb":11,"cmb_special":"+15 sunder","cmd":20,"cmd_special":"22 vs. sunder","feats":[{"feat":"Greater Sunder"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Shield Focus"},{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"},{"feat":"Weapon Specialization (longsword)"}],"skills":[{"skill":"Intimidate","value":12},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":12}],"languages":["Common"],"sq":["armor training 1","aura of law","discipline ability (censor)","force of will ability (force of will-charm)","Hellknight armor","Hellknight order (Order of the Rack)"],"gear":"+1 Hellknight plate, +1 heavy steel shield, +1 longsword, composite longbow (+2 Str) with 20 arrows, cloak of resistance +1, 315 gp","during_combat":"If faced in area D2, the Hellknights stand behind the barricades and fire arrows at the PCs. Otherwise, they prefer to fight in teams, attempting to flank foes if possible and using Greater Sunder with Power Attack to smash through enemy weaponry. They assume all PCs are chaotic and use smite chaos on their first targets unless they have the opportunity to use detect chaos and make more informed decisions.","morale":"The Hellknights fight to the death.","source":"AP 100, Pathfinder Campaign Setting: The Inner Sea World Guide 278"},{"name":"The First Warden","cr":12,"xp":19200,"race":"human","age_category":"Adult","classes":[{"class":"warpriest of asmodeus","level":11}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["human","humanoid"],"templates_applied":"lich","init":5,"senses":["darkvision 60 ft."],"auras":["fear (DC 20)"],"ac":31,"ac_touch":15,"ac_flat_footed":29,"ac_mods":"+11 armor, +3 deflection, +1 Dex, +1 dodge, +5 natural","hp":130,"hd":"11d8+77","hd_value":11,"fort":12,"ref":6,"will":12,"save_mods":"+4 bonus vs. channeled energy","defensive_abilities":["channel resistance +4","rejuvenation","sacred armor (+2, 11 minutes/day)"],"dr":"15/bludgeoning and magic","immunities":["cold","electricity","polymorph","undead traits"],"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+2 merciful heavy mace +12 (1d10+3 nonlethal/19-20 plus 1d6 nonlethal), touch +4 (1d8+5 negative energy plus paralyzing touch)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blessings","details":"8/day"},{"type":"channel negative energy","details":"5/day, DC 20, 6d6"},{"type":"fervor","details":"10/day, 4d6"},{"type":"paralyzing touch","details":"DC 20"},{"type":"sacred weapon","details":"+2 1d10, 11 rounds/day"}],"spellsprepared_caster":"warpriest","spellsprepared_caster_level":11,"spellsprepared_concentration":16,"spellsprepared":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"divine power"},{"spell":"order's wrath"},{"spell":"summon monster IV"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"bestow curse"},{"spell":"create food and water"},{"spell":"dispel magic","count":2},{"spell":"invisibility purge"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"hold person","count":2},{"spell":"silence"},{"spell":"spiritual weapon","count":2}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command","count":3},{"spell":"divine favor"},{"spell":"doom"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"resistance"}]}],"strength":12,"dexterity":13,"intelligence":12,"wisdom":21,"charisma":20,"baseatk":8,"cmb":9,"cmd":24,"feats":[{"feat":"Combat Casting"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Improved Critical (heavy mace)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Step Up"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (heavy mace)"}],"skills":[{"skill":"Intimidate","value":19},{"skill":"Knowledge (religion)","value":15},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":27},{"skill":"Stealth","value":4}],"languages":["Common","Infernal"],"sq":["blessings (fire: armor of flame, fire strike, law: axiomatic strike, battle companion)"],"gear":"+2 full plate, +1 merciful heavy mace, headband of mental prowess +2 (Wis, Cha)","before_combat":"The First Warden casts shield of faith before combat, uses her sacred weapon ability to bolster her mace to an enhancement bonus of +2, and uses her sacred armor ability to grant her full plate the light fortification special ability.","during_combat":"Once driven to attack, the First Warden calls upon the phantom armors standing guard in area D11 to join her, then casts summon monster IV to summon 1d3 fiendish constrictor snakes to fight for her. She also expends a use of fervor on that first round to cast divine power on herself as a swift action, then does so again on the second round to cast divine favor on herself. On following rounds, she continues to use fervor to heal herself each round with the most powerful inflict spells she can cast.","morale":"The First Warden fights until destroyed, trusting that her phylactery will reform a new body a few days after her defeat. She doesn't quite realize, though, that her phylactery is now stored in a long-forgotten vault deep under her family's old estate in Egorian-and the estate was claimed by a rival family after her kin died out. As a result, if she's defeated, she reforms in a forgotten crypt below a distant city, where she may well serve as a plot device for a future adventure of your design, but is unable to return to Kintargo anytime soon.","source":"AP 100, Pathfinder RPG Bestiary 188, Pathfinder RPG Advanced Class Guide 60"},{"name":"Jackdaw","cr":10,"xp":9600,"race":"elf","gender":"Female","age_category":"middle age","classes":[{"class":"swashbuckler","level":11}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["elf"],"init":5,"senses":["low-light vision"],"ac":17,"ac_touch":17,"ac_flat_footed":10,"ac_mods":"+3 Dex, +4 dodge","hp":54,"hd":"11d10-11","hd_value":11,"fort":1,"ref":10,"will":4,"save_mods":"+2 vs. enchantments","defensive_abilities":["charmed life 5/day","evasion","nimble +3","uncanny dodge"],"immunities":["sleep"],"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +9 (1d3-2 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"deeds","details":"bleeding wound, derring-do, dodging panache, evasive, kip-up, menacing swordplay, opportune parry and riposte, precise strike, subtle blade, superior feint, swashbuckler initiative, swashbuckler's grace, targeted strike"},{"type":"panache","details":"3"},{"type":"swashbuckler weapon training +2"}],"strength":7,"dexterity":16,"constitution":7,"intelligence":16,"wisdom":13,"baseatk":11,"cmb":9,"cmd":26,"feats":[{"feat":"Combat Reflexes"},{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Spring Attack"},{"feat":"Weapon Focus (starknife)"}],"skills":[{"skill":"Acrobatics","value":17},{"skill":"Bluff","value":17},{"skill":"Disguise","value":14},{"skill":"Intimidate","value":17},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":14}],"languages":["Common","Celestial","Elven","Gnome","Sylvan"],"sq":["dare","elven magic","swashbuckler finesse"],"during_combat":"Jackdaw uses her ragged nails to make unarmed strikes against the PCs as soon as they enter her cell, drawing attacks of opportunity with each attack. She won't stand down until her Charisma drain from the long years of isolation and insanity is healed, and will need to be restrained until this issue can be addressed if the PCs lack a method of healing her.","morale":"Jackdaw fights to the death while insane, but once cured and restored, she flees combat if reduced to fewer than 10 hp-unless doing so endangers an ally, in which case she'll fight to the death to defend that friend.","source":"AP 100, Pathfinder RPG Advanced Class Guide 56"}];
